from pathlib import Path
import re
r=Path('.')
# AddLocality
p=r/'src/app/dashboard/localities/new/components/AddLocalityForm.tsx'; s=p.read_text()
marker='interface AddLocalityFormProps {\n  initialForm?: LocalityFormState;\n  localityId?: string;\n}'
if 'const PRICE_UNITS' not in s:
 s=s.replace(marker, marker+'''\n\nconst PRICE_UNITS = [{ value: "L", label: "Lakhs" }, { value: "Cr", label: "Cr" }, { value: "/sq.ft.", label: "/sq.ft." }];\nconst DISTANCE_UNITS = [{ value: "km", label: "km" }, { value: "mins", label: "mins" }];\nconst WHY_BUY_PRESETS = [\n  { label: "Strong rental demand", info: "Good rental potential from nearby employment hubs" },\n  { label: "IT employment hubs", info: "Close to major IT and employment corridors" },\n  { label: "Metro connectivity", info: "Improving access through metro connectivity" },\n  { label: "Social infrastructure", info: "Schools, hospitals and daily conveniences nearby" },\n  { label: "Growth potential", info: "Strong infrastructure and development potential" },\n  { label: "Established locality", info: "Established residential and commercial ecosystem" },\n];''')
s=s.replace('<FieldLabel required>Short Description</FieldLabel>','<FieldLabel required>Tagline</FieldLabel>',1)
s=s.replace('placeholder="Enter a short description (max 200 characters)"','placeholder="Enter a short locality tagline"',1)
# replace average/price exact one-line blocks
s=re.sub(r'<div><FieldLabel required>Average Price</FieldLabel><TextInput value=\{form\.averagePrice\}[\s\S]*?<FieldError message=\{errors\.averagePrice\} /></div>', '''<div>\n                  <FieldLabel required>Average Price</FieldLabel>\n                  <div className="grid grid-cols-[1fr_auto] gap-2">\n                    <TextInput value={form.averagePriceValue} onChange={(v) => set("averagePriceValue", v.replace(/[^0-9.,]/g, ""))} placeholder="e.g. 6500" error={errors.averagePrice} />\n                    <select value={form.averagePriceUnit} onChange={(e) => set("averagePriceUnit", e.target.value)} className="rounded-lg border border-line bg-white px-3 text-sm text-ink outline-none">{PRICE_UNITS.map((u) => <option key={u.value} value={u.value}>{u.label}</option>)}</select>\n                  </div>\n                  <FieldError message={errors.averagePrice} />\n                </div>''',s,count=1)
s=re.sub(r'<div><FieldLabel required>Price Range</FieldLabel><TextInput value=\{form\.priceRange\}[\s\S]*?<FieldError message=\{errors\.priceRange\} /></div>', '''<div>\n                  <FieldLabel required>Price Range</FieldLabel>\n                  <div className="grid grid-cols-2 gap-2">\n                    <div className="grid grid-cols-[1fr_auto] gap-1"><TextInput value={form.priceRangeMin} onChange={(v) => set("priceRangeMin", v.replace(/[^0-9.,]/g, ""))} placeholder="Min" error={errors.priceRange} /><select value={form.priceRangeMinUnit} onChange={(e) => set("priceRangeMinUnit", e.target.value)} className="rounded-lg border border-line bg-white px-2 text-xs text-ink"><option value="L">L</option><option value="Cr">Cr</option></select></div>\n                    <div className="grid grid-cols-[1fr_auto] gap-1"><TextInput value={form.priceRangeMax} onChange={(v) => set("priceRangeMax", v.replace(/[^0-9.,]/g, ""))} placeholder="Max" error={errors.priceRange} /><select value={form.priceRangeMaxUnit} onChange={(e) => set("priceRangeMaxUnit", e.target.value)} className="rounded-lg border border-line bg-white px-2 text-xs text-ink"><option value="L">L</option><option value="Cr">Cr</option></select></div>\n                  </div>\n                  <FieldError message={errors.priceRange} />\n                </div>''',s,count=1)
# rows
s=s.replace('{ key: "info", placeholder: "e.g. 2.5 km" },','{ key: "info", placeholder: "e.g. 2.5" },\n                    { key: "infoUnit", placeholder: "", type: "select", options: DISTANCE_UNITS },',1)
s=s.replace('emptyRow={{ label: "", info: "" }}','emptyRow={{ label: "", info: "", infoUnit: "km" }}',1)
s=s.replace('{ label, info: "" }','{ label, info: "", infoUnit: "km" }')
s=s.replace('{ key: "price", placeholder: "e.g. ₹5,200/sq.ft" },','{ key: "price", placeholder: "e.g. 5200" },\n                    { key: "priceUnit", placeholder: "", type: "select", options: [{ value: "/sq.ft.", label: "/sq.ft." }, { value: "L", label: "Lakhs" }, { value: "Cr", label: "Cr" }] },',1)
# only price trend empty row (find after period)
s=s.replace('emptyRow={{ period: "", price: "" }}','emptyRow={{ period: "", price: "", priceUnit: "/sq.ft." }}',1)
# why buy presets
if 'WHY_BUY_PRESETS.map' not in s:
 needle='<FieldError message={errors.whyBuy} />'
 pos=s.find(needle,s.find('title="Why Buy"'))
 if pos!=-1:
  insert='''<div className="mt-3 flex flex-wrap gap-2">{WHY_BUY_PRESETS.map((preset) => (<button key={preset.label} type="button" onClick={() => set("whyBuy", [...form.whyBuy, preset])} className="rounded-lg border border-line bg-white px-2.5 py-2 text-xs font-semibold text-muted hover:border-gold/60 hover:bg-surface hover:text-navy">+ {preset.label}</button>))}</div>\n              '''
  s=s[:pos]+insert+s[pos:]
# numbering
for a,b in [('id="section-why-buy" number={6}','id="section-why-buy" number={5}'),('id="section-about" number={7}','id="section-about" number={6}'),('id="section-images"\n              number={8}','id="section-images"\n              number={7}'),('id="section-publishing"\n              number={9}','id="section-publishing"\n              number={8}')]: s=s.replace(a,b)
# validation scroll
old='''    if (hasErrors(validationErrors)) {\n      document.getElementById("section-basic")?.scrollIntoView({ behavior: "smooth" });\n      return;\n    }'''
if old in s:
 new='''    if (hasErrors(validationErrors)) {\n      const sectionByField: Record<string, string> = { name: "section-basic", slug: "section-basic", city: "section-basic", shortDescription: "section-overview", fullDescription: "section-overview", averagePrice: "section-overview", priceRange: "section-overview", popularBhk: "section-overview", infrastructure: "section-connectivity", connectivity: "section-connectivity", priceTrends: "section-price-trends", whyBuy: "section-why-buy", aboutTitle: "section-about", aboutDescription: "section-about", heroImageUrl: "section-images", mainImageUrl: "section-images", aboutImageUrl: "section-images" };\n      const firstKey = Object.keys(validationErrors)[0];\n      document.getElementById(sectionByField[firstKey] ?? "section-basic")?.scrollIntoView({ behavior: "smooth", block: "start" });\n      return;\n    }'''
 s=s.replace(old,new,1)
p.write_text(s)

# Builder remove fields
