p=r/'src/app/dashboard/builders/[id]/edit/builder-to-form.ts'; s=p.read_text().replace('  founded_year: number | null;\n  headquarters: string | null;\n','').replace('    foundedYear: row.founded_year ? String(row.founded_year) : "",\n    headquarters: row.headquarters ?? "",\n',''); p.write_text(s)
