p=r/'src/app/dashboard/localities/components/LocalitiesTable.tsx'; s=p.read_text().replace('              <th className="w-[15%] px-4 py-3 font-bold">Status</th>\n','').replace('                  <PublishedBadge published={locality.published} />\n',''); p.write_text(s)
